const settings = $('Read Dialer Settings').first().json;

// تجاهل العنصر الفارغ الناتج عن Always Output Data
const activeCalls = $input
  .all()
  .filter(item => item.json && Object.keys(item.json).length > 0)
  .length;

const maxConcurrentCalls = Number(
  settings['Max Concurrent Calls'] || 0
);

const rawDialerEnabled = settings['Dialer Enabled'];

const dialerEnabled =
  rawDialerEnabled === true ||
  rawDialerEnabled === 1 ||
  ['TRUE', 'YES', '1', 'ON'].includes(
    String(rawDialerEnabled ?? '').trim().toUpperCase()
  );

const availableSlots = dialerEnabled
  ? Math.max(0, maxConcurrentCalls - activeCalls)
  : 0;

return [
  {
    json: {
      dialer_enabled: dialerEnabled,
      max_concurrent_calls: maxConcurrentCalls,
      active_calls: activeCalls,
      available_slots: availableSlots
    }
  }
];

const settings = $('Read Dialer Settings').first().json;
const slotData = $('Calculate Available Slots').first().json;

// --------------------------------------------------
// 1) حساب المكالمات المنتهية اليوم
// --------------------------------------------------

// نتجاهل العنصر الفارغ الناتج عن Always Output Data
const finishedCallsToday = $input
  .all()
  .filter(
    item =>
      item.json &&
      Object.keys(item.json).length > 0
  )
  .length;


// --------------------------------------------------
// 2) قراءة إعدادات الدايالر
// --------------------------------------------------

const dailyCallLimit = Number(
  settings['Daily Call Limit'] || 0
);

const activeCalls = Number(
  slotData.active_calls || 0
);

const availableSlots = Number(
  slotData.available_slots || 0
);

const dialerEnabled =
  slotData.dialer_enabled === true;

const callingStartTime =
  settings['Calling Start Time'];

const callingEndTime =
  settings['Calling End Time'];


// --------------------------------------------------
// 3) تحويل وقت الشيت إلى عدد دقائق
// --------------------------------------------------

function timeToMinutes(value) {
  if (value === null || value === undefined || value === '') {
    return null;
  }

  // في حال أرجع Google Sheets الوقت كرقم عشري
  if (typeof value === 'number') {
    if (value >= 0 && value < 1) {
      return Math.round(value * 24 * 60) % 1440;
    }
  }

  const text = String(value).trim().toUpperCase();

  // يدعم 10:00 و10:00:00 و10:00 AM
  const match = text.match(
    /^(\d{1,2}):(\d{2})(?::\d{2})?\s*(AM|PM)?$/
  );

  if (!match) {
    return null;
  }

  let hours = Number(match[1]);
  const minutes = Number(match[2]);
  const period = match[3];

  if (
    Number.isNaN(hours) ||
    Number.isNaN(minutes) ||
    minutes < 0 ||
    minutes > 59
  ) {
    return null;
  }

  if (period === 'AM' && hours === 12) {
    hours = 0;
  }

  if (period === 'PM' && hours < 12) {
    hours += 12;
  }

  if (hours < 0 || hours > 23) {
    return null;
  }

  return (hours * 60) + minutes;
}


// --------------------------------------------------
// 4) التحقق من ساعات الاتصال بتوقيت السعودية
// --------------------------------------------------

const nowSaudi = $now.setZone('Asia/Riyadh');

const currentMinutes =
  (nowSaudi.hour * 60) + nowSaudi.minute;

const startMinutes =
  timeToMinutes(callingStartTime);

const endMinutes =
  timeToMinutes(callingEndTime);

let withinCallingHours = false;

if (
  startMinutes !== null &&
  endMinutes !== null
) {
  if (startMinutes < endMinutes) {
    // مثال: 10:00 إلى 18:00
    withinCallingHours =
      currentMinutes >= startMinutes &&
      currentMinutes < endMinutes;
  } else if (startMinutes > endMinutes) {
    // يدعم وقتًا يعبر منتصف الليل
    // مثال: 20:00 إلى 02:00
    withinCallingHours =
      currentMinutes >= startMinutes ||
      currentMinutes < endMinutes;
  } else {
    // لو وقت البداية والنهاية متساويان
    // نعتبر الاتصال مسموحًا طوال اليوم
    withinCallingHours = true;
  }
}


// --------------------------------------------------
// 5) حساب الحد اليومي
// --------------------------------------------------

// مكالمات اليوم = المنتهية اليوم + الشغالة حاليًا
const callsStartedToday =
  finishedCallsToday + activeCalls;

const remainingDailyCalls = Math.max(
  0,
  dailyCallLimit - callsStartedToday
);


// --------------------------------------------------
// 6) تحديد عدد المكالمات المسموح بدؤها الآن
// --------------------------------------------------

const callsToStart =
  dialerEnabled && withinCallingHours
    ? Math.max(
        0,
        Math.min(
          availableSlots,
          remainingDailyCalls
        )
      )
    : 0;


// --------------------------------------------------
// 7) إخراج النتيجة
// --------------------------------------------------

return [
  {
    json: {
      dialer_enabled: dialerEnabled,

      calling_start_time: String(
        callingStartTime ?? ''
      ),

      calling_end_time: String(
        callingEndTime ?? ''
      ),

      current_time_saudi:
        nowSaudi.toFormat('HH:mm'),

      within_calling_hours:
        withinCallingHours,

      max_concurrent_calls: Number(
        slotData.max_concurrent_calls || 0
      ),

      active_calls: activeCalls,
      available_slots: availableSlots,

      daily_call_limit: dailyCallLimit,
      finished_calls_today: finishedCallsToday,
      calls_started_today: callsStartedToday,
      remaining_daily_calls: remainingDailyCalls,

      calls_to_start: callsToStart
    }
  }
];

